package com.ledgerguard.lock; import org.springframework.stereotype.Service; import java.time.Duration; import java.time.Instant; import java.util.Optional; import java.util.UUID; import java.util.concurrent.ConcurrentHashMap; import java.util.function.Supplier; @Service public class RedisLockServiceImpl implements LockService { private record LockEntry(String token, long expiresAtNanos) {} private final ConcurrentHashMap<String, LockEntry> locks = new ConcurrentHashMap<>(); @Override public Optional<LockHandle> tryAcquire(String resourceKey, Duration ttl, Duration maxWait) { long nowNs = System.nanoTime(); long ttlNanos = ttl != null && !ttl.isNegative() && !ttl.isZero() ? ttl.toNanos() : Duration.ofSeconds(30).toNanos(); long deadlineNs = nowNs + (maxWait != null && !maxWait.isNegative() ? maxWait.toNanos() : 0L); String token = UUID.randomUUID().toString(); while (true) { long currentNs = System.nanoTime(); locks.compute(resourceKey, (k, existing) -> { if (existing == null || existing.expiresAtNanos() <= currentNs) { return new LockEntry(token, currentNs + ttlNanos); } return existing; }); LockEntry current = locks.get(resourceKey); if (current != null && token.equals(current.token())) { return Optional.of(new LockHandle(resourceKey, token, Instant.now(), ttl)); } if (System.nanoTime() >= deadlineNs) { return Optional.empty(); } try { Thread.sleep(25L); } catch (InterruptedException ie) { Thread.currentThread().interrupt(); return Optional.empty(); } } } @Override public void release(LockHandle handle) { if (handle == null || handle.key() == null || handle.token() == null) { return; } locks.computeIfPresent(handle.key(), (k, existing) -> handle.token().equals(existing.token()) ? null : existing); } @Override public <T> T withLock(String resourceKey, Duration ttl, Duration maxWait, Supplier<T> action) { LockHandle handle = tryAcquire(resourceKey, ttl, maxWait).orElseThrow(() -> new IllegalStateException("Could not acquire lock: " + resourceKey)); try { return action.get(); } finally { release(handle); } } }